CREATE TABLE "Item" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"frName" text,
	"shortName" text,
	"category" "Category" NOT NULL,
	"superClass" "SuperClass" NOT NULL,
	"class" "Class" NOT NULL,
	"faction" "Faction" DEFAULT 'NEUTRAL' NOT NULL,
	"nbByCrate" integer DEFAULT 100 NOT NULL,
	"maxQuantity" integer DEFAULT 100 NOT NULL,
	"icon" text,
	"attributes" jsonb,
	"createdAt" timestamp (3) DEFAULT now() NOT NULL,
	"updatedAt" timestamp (3) DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "Location" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"type" "LocationType" DEFAULT 'SEAPORT' NOT NULL,
	"faction" "Faction" DEFAULT 'NEUTRAL' NOT NULL,
	"iconType" integer DEFAULT 0 NOT NULL,
	"flags" integer DEFAULT 0 NOT NULL,
	"viewDirection" integer DEFAULT 0 NOT NULL,
	"longitude" double precision NOT NULL,
	"latitude" double precision NOT NULL,
	"townId" uuid NOT NULL,
	"regionId" uuid NOT NULL
);
--> statement-breakpoint
CREATE TABLE "Region" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"gameRegionId" integer
);
--> statement-breakpoint
CREATE TABLE "Town" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"longitude" double precision NOT NULL,
	"latitude" double precision NOT NULL,
	"mapMarkerType" "MapMarkerType" NOT NULL,
	"regionId" uuid NOT NULL
);
--> statement-breakpoint
ALTER TABLE "Location" ADD CONSTRAINT "Location_townId_fkey" FOREIGN KEY ("townId") REFERENCES "public"."Town"("id") ON DELETE restrict ON UPDATE cascade;--> statement-breakpoint
ALTER TABLE "Location" ADD CONSTRAINT "Location_regionId_fkey" FOREIGN KEY ("regionId") REFERENCES "public"."Region"("id") ON DELETE restrict ON UPDATE cascade;--> statement-breakpoint
ALTER TABLE "Town" ADD CONSTRAINT "Town_regionId_fkey" FOREIGN KEY ("regionId") REFERENCES "public"."Region"("id") ON DELETE restrict ON UPDATE cascade;--> statement-breakpoint
