CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW."updatedAt" = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER item_updated_at
  BEFORE UPDATE ON "Item"
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();--> statement-breakpoint